package com.ecoresolve.config;
import com.ecoresolve.entity.User; import com.ecoresolve.enums.Role; import com.ecoresolve.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration @RequiredArgsConstructor public class AdminInitializer implements CommandLineRunner { private final UserRepository users; private final PasswordEncoder encoder; @Value("${ADMIN_EMAIL:admin@ecoresolve.local}") String email; @Value("${ADMIN_PASSWORD:Admin@12345}") String password; @Value("${ADMIN_NAME:EcoResolve Admin}") String name; public void run(String...a){if(email.isBlank()||password.isBlank()||users.existsByEmail(email.toLowerCase()))return;User u=new User();u.setName(name);u.setEmail(email.toLowerCase());u.setPasswordHash(encoder.encode(password));u.setRole(Role.ADMIN);users.save(u);} }
